<script setup lang="ts">import{num,price}from'@/utils/format';import type{Drink}from'@/types/cafe';defineProps<{open:boolean;items:{drink:Drink;q:number}[];count:number;total:number;table:number;notes:string;submitting:boolean}>();defineEmits<{close:[];add:[id:string];remove:[id:string];'update:notes':[value:string];submit:[]}>()</script><template><Teleport to="body"><button v-if="open" class="ov on" aria-label="إغلاق السلة" @click="$emit('close')"/><aside class="sheet" :class="{on:open}"><div class="sh"><b>سلة الطلب — طاولة {{num(table)}}</b><button class="sx" @click="$emit('close')">×</button></div><div class="sb"><div v-for="x in items" :key="x.drink.id" class="qitem"><img :src="x.drink.img" :alt="x.drink.n"><span class="qi2"><b>{{x.drink.n}}</b><span class="p">{{price(x.drink.pr)}}</span></span><span class="qtyc"><button @click="$emit('remove',x.drink.id)">−</button><span>{{num(x.q)}}</span><button @click="$emit('add',x.drink.id)">+</button></span></div><textarea class="note-in" :value="notes" maxlength="500" @input="$emit('update:notes',($event.target as HTMLTextAreaElement).value)"/></div><footer class="sf"><div class="srow"><span>عدد الأصناف</span><span>{{num(count)}}</span></div><div class="srow t"><span>الإجمالي</span><b>{{price(total)}}</b></div><button class="btn-g submit" :disabled="submitting" @click="$emit('submit')">{{submitting?'جاري إرسال الطلب…':'✓ تأكيد الطلب وإرساله للمقهى'}}</button></footer></aside></Teleport></template>
